def get_grid(s,h):
 return [[int(v) for v in line.split()] for line in s.strip().splitlines()[:h]]
seen=set()
for (text,) in msgs:
 for n in range(1,9):
  m=re.search(rf'Demo pair {n} input \((\d+)x(\d+)\):\n',text)
  if not m: continue
  h,w=map(int,m.groups()); key=(n,h,w)
  if key in seen: continue
  seen.add(key)
  end=m.end(); om=re.search(rf'Demo pair {n} output \((\d+)x(\d+)\):\n',text[end:])
  if not om: print('no output',n); continue
  is_=text[end:end+om.start()]; os_=text[end+om.end():]
  ogseg=os_.split('\n\nSame instance',1)[0]
  try: ig=get_grid(is_,h); og=get_grid(ogseg,h)
  except Exception as e: print('parse',n,e); continue
  if len(ig)!=h or len(og)!=h or any(len(r)!=w for r in ig+og): print('dims bad',n);continue
  bg=Counter(v for row in ig for v in row).most_common(1)[0][0]
  changed=[(r,x,ig[r][x],og[r][x]) for r in range(h) for x in range(w) if ig[r][x]!=og[r][x]]
  color=changed[0][2]; pts={(r,x) for r,x,a,b in changed}
  # find same-color 4connected object covering changed points
  components=[]; visited=set()
  for r in range(h):
   for x in range(w):
    if ig[r][x]!=color or (r,x) in visited: continue
    q=[(r,x)]; visited.add((r,x)); obj=[]
    while q:
     a,b=q.pop(); obj.append((a,b))
     for y,z in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
      if 0<=y<h and 0<=z<w and ig[y][z]==color and (y,z) not in visited:visited.add((y,z));q.append((y,z))
    if pts.issubset(set(obj)): components.append(obj)
